import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import gsap from 'gsap';
// Note: '@/text' import is not used directly; ctx.fontAtlas is used instead.

export default function createNode(config, ctx) {
  const { scenePosition, scale, rotation, textContent } = config;
  const group = new Group();

  // Load the brushed-metal texture
  const texture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');

  // Create the label background plane
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ map: texture });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Extract text configuration (first element in textContent array)
  const textConfig = textContent?.[0] || { text: 'Journal 1', style: 'headline', weight: 400 };
  const fontSize = 0.34; // headline scene-unit em

  // Create text mesh using the font atlas
  const textMesh = ctx.fontAtlas.createText(textConfig.text, {
    fontFamily: 'Lora',
    fontWeight: textConfig.weight || 400,
    fontSize: fontSize,
    color: '#e8ecf2', // paper color for contrast
    align: 'center'
  });
  // Slight Z offset to prevent z-fighting with background
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  // Apply spatial properties
  group.position.copy(scenePosition);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.copy(scale);

  // Event handlers (none for this static label)
  group.userData.handlers = {};

  // Cleanup resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
